-- 095 is already applied: preserve it and extend only daily client/supplier
-- creation. Their codes are generated by the existing migration 002 trigger.
begin;

create or replace function app_private.guard_operator_numbering_write()
returns trigger language plpgsql security invoker
set search_path = public, app_private
as $$
begin
  if app_private.is_operator_org_member(new.organization_id)
    or (tg_op = 'UPDATE' and app_private.is_operator_org_member(old.organization_id)) then
    if pg_trigger_depth() < 2
      or new.document_type !~ '^(CUSTOMER_(INVOICE|PAYMENT)|THIRD_PARTY_(customer|supplier))_[0-9]{4}$' then
      raise exception 'OPERATOR_NUMBERING_READ_ONLY' using errcode = '42501';
    end if;
    if tg_op = 'UPDATE' and (
      new.next_number <> old.next_number + 1
      or (to_jsonb(new) - array['next_number','updated_at'])
        is distinct from (to_jsonb(old) - array['next_number','updated_at'])
    ) then
      raise exception 'OPERATOR_NUMBERING_READ_ONLY' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

-- The current client/supplier forms use these tables, rather than the legacy
-- contacts table. Keep other roles' rules and permit only an own-tenant parent.
do $$
declare
  target_table text;
  operator_check text;
begin
  foreach target_table in array array['third_party_contacts','third_party_addresses']
  loop
    if to_regclass('public.' || target_table) is null then continue; end if;
    if not (select relrowsecurity from pg_class where oid = to_regclass('public.' || target_table)) then
      raise exception 'RLS_DISABLED_REQUIRES_REVIEW: %', target_table;
    end if;
    operator_check := '(not app_private.is_operator_org_member(organization_id) or exists (' ||
      'select 1 from public.third_parties parent where parent.id = ' || quote_ident(target_table) || '.third_party_id ' ||
      'and parent.organization_id = ' || quote_ident(target_table) || '.organization_id ' ||
      'and parent.primary_type in (''customer'',''supplier'')))';
    execute format('drop policy if exists operator_insert_guard_v5 on public.%I', target_table);
    execute format('drop policy if exists operator_update_guard_v5 on public.%I', target_table);
    execute format('drop policy if exists operator_delete_guard_v5 on public.%I', target_table);
    execute format('create policy operator_insert_guard_v5 on public.%I as restrictive for insert to authenticated with check (%s)', target_table, operator_check);
    execute format('create policy operator_update_guard_v5 on public.%I as restrictive for update to authenticated using (%s) with check (%s)', target_table, operator_check, operator_check);
    execute format('create policy operator_delete_guard_v5 on public.%I as restrictive for delete to authenticated using (%s)', target_table, operator_check);
  end loop;
end;
$$;

commit;

-- Read-back verification: the SQL Editor must display three true values.
select
  position('THIRD_PARTY_' in pg_get_functiondef('app_private.guard_operator_numbering_write()'::regprocedure)) > 0
    as correctif_096_actif,
  exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'third_party_contacts'
    and policyname = 'operator_insert_guard_v5' and position('primary_type' in with_check) > 0)
    as contacts_operateur_actifs,
  exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'third_party_addresses'
    and policyname = 'operator_insert_guard_v5' and position('primary_type' in with_check) > 0)
    as adresses_operateur_actives;
